_renderTicks(size) {
  try {
    var canvas = this.$element("tickCanvas")
    if (!canvas) { return }
    var ctx = canvas.getContext("2d")
    if (!ctx) { return }
    var cx = size / 2
    var cy = size / 2
    ctx.clearRect(0, 0, size, size)
    // 外圈细环
    ctx.beginPath()
    ctx.lineWidth = 1.5
    ctx.strokeStyle = "rgba(255,255,255,0.14)"
    ctx.arc(cx, cy, size / 2 - 6, 0, Math.PI * 2)
    ctx.stroke()
    // 60 刻度（每 5 格一条主刻度）
    for (var i = 0; i < 60; i++) {
      var ang = (i / 60) * Math.PI * 2 - Math.PI / 2
      var isMajor = (i % 5 === 0)
      var r1 = size / 2 - 9
      var r2 = size / 2 - (isMajor ? 18 : 14)
      ctx.beginPath()
      ctx.lineWidth = isMajor ? 2.5 : 1
      ctx.strokeStyle = isMajor ? "rgba(255,255,255,0.45)" : "rgba(255,255,255,0.16)"
      ctx.moveTo(cx + r1 * Math.cos(ang), cy + r1 * Math.sin(ang))
      ctx.lineTo(cx + r2 * Math.cos(ang), cy + r2 * Math.sin(ang))
      ctx.stroke()
    }
    // 秒针（每秒更新）
    var now = new Date()
    var sec = now.getSeconds()
    var secAng = (sec / 60) * Math.PI * 2 - Math.PI / 2
    var secR1 = size / 2 - 22
    var secR2 = size / 2 - 38
    ctx.beginPath()
    ctx.lineWidth = 1.5
    ctx.strokeStyle = "rgba(62,230,176,0.6)"
    ctx.moveTo(cx + secR1 * Math.cos(secAng), cy + secR1 * Math.sin(secAng))
    ctx.lineTo(cx + secR2 * Math.cos(secAng), cy + secR2 * Math.sin(secAng))
    ctx.stroke()
    // 秒针尾端小圆点
    ctx.beginPath()
    ctx.arc(cx + secR2 * Math.cos(secAng), cy + secR2 * Math.sin(secAng), 2, 0, Math.PI * 2)
    ctx.fillStyle = "rgba(62,230,176,0.8)"
    ctx.fill()
  } catch (e) { /* canvas 不可用时降级为无刻度 */ }
},

