onAccelSample(sample) {
  if (this.liveAlertLocked) { return }
  sample.timestamp = Date.now()
  pushSample(this.sampleWindow, sample)
  this.liveSampleCount += 1
  var steps = processStepDetection(sample)
  this.stepCount = steps
  this.stepProgress = Math.min(Math.round((steps / STEP_GOAL) * 100), 100)
  if (this.stepProgress !== this.lastDrawnProgress) {
    this.lastDrawnProgress = this.stepProgress
    this.drawDialRing()
  }

  var g = Math.sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z)
  this.peakG = Math.max(Number(this.peakG), g).toFixed(2)

  var trend = getPressureTrend()
  if (trend.trend === "falling") { this.pressureHint = "下降" }
  else if (trend.trend === "rising") { this.pressureHint = "上升" }
  else { this.pressureHint = "" }

  // 两阶段检测：冲击候选 → 持续静止确认，避免 4 秒窗口单次命中即误报
  var hit = this.detector.push(sample)
  if (hit && Date.now() - this.lastAlertTime >= 30000) {
    this.liveAlertLocked = true
    this.lastAlertTime = Date.now()
    this.openAlert(createAlert(this.buildResultFor(hit), "真机 IMU"))
  }
},

input.new_string:
onAccelSample(sample) {
  if (this.liveAlertLocked) { return }
  sample.timestamp = Date.now()
  pushSample(this.sampleWindow, sample)
  this.liveSampleCount += 1

  // 步数检测：每次回调都需要（精度依赖高频采样）
  var steps = processStepDetection(sample)
  this.stepCount = steps
  this.stepProgress = Math.min(Math.round((steps / STEP_GOAL) * 100), 100)
  if (this.stepProgress !== this.lastDrawnProgress) {
    this.lastDrawnProgress = this.stepProgress
    this.drawDialRing()
  }

  // peakG 更新（纯数值运算，开销极低）
  var g = Math.sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z)
  this.peakG = Math.max(Number(this.peakG), g).toFixed(2)

  // 气压趋势：每 10 个样本检查一次（气压变化缓慢）
  if (this.liveSampleCount % 10 === 0) {
    var trend = getPressureTrend()
    if (trend.trend === "falling") { this.pressureHint = "下降" }
    else if (trend.trend === "rising") { this.pressureHint = "上升" }
    else { this.pressureHint = "" }
  }

  // 两阶段检测：冲击候选 → 持续静止确认
  var hit = this.detector.push(sample)
  if (hit && Date.now() - this.lastAlertTime >= 30000) {
    this.liveAlertLocked = true
    this.lastAlertTime = Date.now()
    this.openAlert(createAlert(this.buildResultFor(hit), "真机 IMU"))
  }
},

