/**
 * utils.js - 公共工具函数
 *
 * 消除 history.ux / all-events.ux / event-detail.ux 间的代码重复。
 */

/**
 * 补零（个位数前补 0）
 * @param {number} v
 * @returns {string}
 */
export function padZero(v) {
  return v < 10 ? "0" + v : String(v)
}

/**
 * 格式化完整时间标签（含年月日时分秒）
 * @param {object} event - 事件对象
 * @returns {string}
 */
export function fullTimeLabel(event) {
  if (!event.createdAt) return event.timeLabel || ""
  var d = new Date(event.createdAt)
  return d.getFullYear() + "-" + padZero(d.getMonth() + 1) + "-" + padZero(d.getDate()) + " " +
    padZero(d.getHours()) + ":" + padZero(d.getMinutes()) + ":" + padZero(d.getSeconds())
}

/**
 * 根据事件状态返回图标、图标样式类、状态样式类
 * @param {string} status - 事件状态
 * @returns {object} { icon, iconClass, statusClass, statusLabel }
 */
export function classifyStatus(status) {
  if (status === "cancelled") {
    return { icon: "✓", iconClass: "icon-safe", statusClass: "status-safe", statusLabel: "已取消" }
  }
  if (status === "queued") {
    return { icon: "!", iconClass: "icon-queued", statusClass: "status-queued", statusLabel: "待补发" }
  }
  if (status === "withdrawal_queued") {
    return { icon: "↶", iconClass: "icon-queued", statusClass: "status-queued", statusLabel: "撤回待发" }
  }
  if (status === "withdrawn") {
    return { icon: "✓", iconClass: "icon-withdrawn", statusClass: "status-withdrawn", statusLabel: "已撤回" }
  }
  return { icon: "↑", iconClass: "icon-sent", statusClass: "status-sent", statusLabel: "已发送" }
}

