  if (this.ringTimer) { clearInterval(this.ringTimer); this.ringTimer = null }
},

// 平滑颜色插值：绿(62,230,176) → 黄(255,180,84) → 红(255,93,80)
_ringColor(pct) {
  var r, g, b
  if (pct > 0.5) {
    // 绿 → 黄
    var t = (pct - 0.5) * 2
    r = Math.round(62 + (255 - 62) * (1 - t))
    g = Math.round(230 + (180 - 230) * (1 - t))
    b = Math.round(176 + (84 - 176) * (1 - t))
  } else {
    // 黄 → 红
    var t2 = pct * 2
    r = 255
    g = Math.round(93 + (180 - 93) * t2)
    b = Math.round(80 + (84 - 80) * t2)
  }
  return "rgb(" + r + "," + g + "," + b + ")"
},

drawCountdownRing(pct) {
  try {
    var canvas = this.$element("ringCanvas")
    if (!canvas) { return }
    var ctx = canvas.getContext("2d")
    if (!ctx) { return }
    var size = this.ringW
    var cx = size / 2
    var cy = size / 2
    var r = size / 2 - 8
    var lineWidth = 4

    ctx.clearRect(0, 0, size, size)

    // 底环
    ctx.beginPath()
    ctx.lineWidth = lineWidth
    ctx.strokeStyle = "rgba(255,93,80,0.15)"
    ctx.arc(cx, cy, r, 0, Math.PI * 2)
    ctx.stroke()

    if (pct <= 0) { return }

    // 进度弧（从顶部开始，逆时针减少）
    var endAngle = -Math.PI / 2
    var startAngle = endAngle + Math.PI * 2 * pct

    ctx.beginPath()
    ctx.lineWidth = lineWidth
    ctx.lineCap = "round"
    ctx.strokeStyle = this._ringColor(pct)
    ctx.arc(cx, cy, r, startAngle, endAngle)
    ctx.stroke()
  } catch (e) { /* skip */ }
},

stopRingAnimation() { this.stopCountdown() },
